// [2] The gate. Fires hourly, reads only the Settings table, and decides whether this is the hour to
// do anything at all.
//
// Why hourly instead of a cron set to 05:00: the premise of the whole case is that the database
// decides, and the time of day is part of that. A cron baked into the node would mean "edit the
// workflow to move your brief", which is exactly what this system exists to avoid. The cost is one
// small Notion query per hour; the Topics and Sources tables are only read when the gate opens.
const norm = (s) => String(s || '').trim().toLowerCase();
const isOn = (v) => ['on', 'yes', 'on', 'true', 'yes', '1'].includes(norm(v));

// One Notion query answers with a single object holding every row in `results`, so the rows are
// unwrapped before reading. Looping the items directly would loop once over the envelope.
const rows = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (Array.isArray(j.results)) rows.push(...j.results);
  else if (j.id || j.properties) rows.push(j);
}

const settings = {};
for (const row of rows) {
  const p = row.properties || {};
  const key = norm((p['Key']?.title || []).map((t) => t.plain_text).join('') || row['Key']);
  const val = (p['Value']?.rich_text || []).map((t) => t.plain_text).join('') || row['Value'] || '';
  if (key) settings[key] = String(val).trim();
}

const store = $getWorkflowStaticData('global');
const now = DateTime.now();
const today = now.toISODate();

// "Give me the brief now": a POST to /webhook/run-now skips the hour check and the once-a-day guard.
// It exists because a schedule-only workflow cannot be tried without waiting for tomorrow, and it
// turns out to be worth keeping — an on-demand brief is a feature, not only a test hook.
// Referencing a node that did not run in this execution throws, so the check is guarded.
let forced = false;
try { forced = $('Run now').all().length > 0; } catch { forced = false; }

const config = {
  paused: isOn(settings['pause']),
  briefTime: settings['brief time'] || '05:00',
  weeklyReview: isOn(settings['weekly review']),
  weeklyReviewDay: norm(settings['review day']) || 'sunday',
  reviewNow: isOn(settings['review now']),
  channel: norm(settings['channel']) || 'telegram',
};

const briefHour = Number(String(config.briefTime).split(':')[0]);
const DAYS = { monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5, saturday: 6, sunday: 7 };

// Pause stops everything, including the weekly review. A holiday should be quiet, not half quiet.
// A forced run ignores it: asking for the brief by hand is an explicit answer to "are you on holiday".
if (config.paused && !forced) {
  return [{ json: { run_brief: false, run_review: false, reason: 'paused', config } }];
}

// One brief per day even if the hour is hit twice — a manual run, a restart, a clock change. The last
// run date lives in static data next to the seen-index, so it survives a container restart.
const alreadyToday = store.last_run?.date === today;
const runBrief = forced || (Number.isFinite(briefHour) && now.hour === briefHour && !alreadyToday);

// The review rides along with the brief hour on its day, so the person gets one message, not two at
// odd times. "Review now" jumps the queue and is reset by [43] once it has been sent.
const isReviewDay = now.weekday === (DAYS[config.weeklyReviewDay] ?? 7);
const runReview = config.reviewNow || (config.weeklyReview && isReviewDay && runBrief);

return [{
  json: {
    run_brief: runBrief,
    run_review: runReview,
    forced,
    reason: forced ? 'run now' : runBrief ? 'brief hour' : alreadyToday ? 'already ran today' : `waiting for ${config.briefTime}`,
    config,
    started_at: now.toISO(),
  },
}];

// [2] Load the control panel: Topics, Sources and Settings come in from three Notion nodes and leave
// as one config object. Everything downstream reads this and nothing else, so the prompt never has to
// know what the user cares about — the database does.
//
// Defaults below apply when a field is left empty in Notion. They are the only place in the workflow
// where a number is hard-coded, and each one is also a row in the Settings table, so the user can
// override it without touching this file.
const DEFAULTS = {
  windowHours: 24,      // Topics -> Window
  threshold: 60,        // Topics -> Threshold: score above this ships. NOT a cap on how many ship.
  budgetCeiling: 250,   // Settings -> Budget ceiling: max candidates handed to the model per run
  memoryDays: 30,       // Settings -> Memory window: how long a URL stays in the seen-index
  briefTime: '05:00',
  channel: 'telegram',
  lang: 'en',        // Settings -> Brief language: the digest's own words
  weeklyReviewDay: 'sunday',
};

// n8n's Notion node returns either the raw API page or a "simplified" shape depending on its options
// and version. Reading through one helper means a version bump cannot silently empty a field.
function prop(page, name) {
  const p = (page.properties || {})[name];
  if (p === undefined) return page[name];               // simplified output puts values at the top level
  if (p === null) return null;
  switch (p.type) {
    case 'title': return (p.title || []).map((t) => t.plain_text).join('');
    case 'rich_text': return (p.rich_text || []).map((t) => t.plain_text).join('');
    case 'select': return p.select ? p.select.name : null;
    case 'multi_select': return (p.multi_select || []).map((o) => o.name);
    case 'number': return p.number;
    case 'checkbox': return p.checkbox;
    case 'url': return p.url;
    case 'date': return p.date ? p.date.start : null;
    case 'relation': return (p.relation || []).map((r) => r.id);
    default: return p[p.type] ?? null;
  }
}

// A Notion query answers with ONE object holding a `results` array, so an HTTP node hands this Code
// node a single item containing every row. Iterating the items directly would loop once over the
// envelope and find nothing — which looks exactly like "no active topics" and is why this helper is
// its own named thing rather than an inline expression.
function pages(nodeName) {
  const out = [];
  for (const item of $(nodeName).all()) {
    const j = item.json || {};
    if (Array.isArray(j.results)) out.push(...j.results);
    else if (j.id || j.properties) out.push(j);
  }
  return out;
}

const id = (page) => String(page.id || page.page_id || '').replace(/-/g, '');
const norm = (s) => String(s || '').trim().toLowerCase();
const isOn = (v) => ['on', 'yes', 'on', 'true', 'yes', '1'].includes(norm(v));

// ---------------------------------------------------------------- settings
const settings = {};
for (const page of pages('Notion: Settings')) {
  const key = norm(prop(page, 'Key'));
  if (key) settings[key] = String(prop(page, 'Value') ?? '').trim();
}
const num = (key, fallback) => {
  const n = Number(settings[key]);
  return Number.isFinite(n) && n > 0 ? n : fallback;
};

const config = {
  paused: isOn(settings['pause']),
  channel: norm(settings['channel']) || DEFAULTS.channel,
  briefTime: settings['brief time'] || DEFAULTS.briefTime,
  budgetCeiling: num('budget ceiling', DEFAULTS.budgetCeiling),
  memoryDays: num('memory window', DEFAULTS.memoryDays),
  weeklyReview: isOn(settings['weekly review']),
  weeklyReviewDay: norm(settings['review day']) || DEFAULTS.weeklyReviewDay,
  reviewNow: isOn(settings['review now']),
  // n8n blocks $env inside Code nodes by default, and asking the user to flip a container flag to read
  // one address would be a poor trade. It lives in Settings like everything else the user can set.
  publicBase: String(settings['n8n address'] || 'http://localhost:5678').replace(/\/$/, ''),
  // Which language the digest is written in. The model is told this, and the handful of fixed
  // strings around it follow. Everything else in the system stays English.
  lang: (norm(settings['brief language']) || DEFAULTS.lang).slice(0, 2),
  runDate: DateTime.now().toISODate(),
};

// ---------------------------------------------------------------- topics
const topics = [];
for (const page of pages('Notion: Topics')) {
  if (prop(page, 'Status') !== 'Active') continue;
  const signals = (prop(page, 'Signals') || []).map(norm).filter(Boolean);
  topics.push({
    id: id(page),
    name: prop(page, 'Topic') || '(unnamed)',
    // The text the model judges against. An empty criterion would make every score meaningless,
    // so such a topic is skipped loudly rather than silently mis-scoring everything.
    criterion: (prop(page, 'Criterion') || '').trim(),
    signals,
    // An empty Signals list is a deliberate escape hatch: it turns the keyword filter OFF for this
    // topic, so everything inside the time window reaches the model. Costs more, misses nothing.
    keywordFilter: signals.length > 0,
    minusSignals: (prop(page, 'Muted') || []).map(norm).filter(Boolean),
    languages: prop(page, 'Languages') || [],
    windowHours: Number(prop(page, 'Window')) > 0 ? Number(prop(page, 'Window')) : DEFAULTS.windowHours,
    threshold: Number.isFinite(Number(prop(page, 'Threshold'))) ? Number(prop(page, 'Threshold')) : DEFAULTS.threshold,
    priority: prop(page, 'Priority') || '⚡ Medium',
    wantsDiscovery: prop(page, 'Find sources') === true,
    sourceIds: [],
  });
}

const PRIORITY_ORDER = { '🔥 High': 0, '⚡ Medium': 1, '💤 Low': 2 };
topics.sort((a, b) => (PRIORITY_ORDER[a.priority] ?? 1) - (PRIORITY_ORDER[b.priority] ?? 1));

const brokenTopics = topics.filter((t) => !t.criterion).map((t) => t.name);
const usableTopics = topics.filter((t) => t.criterion);

// ---------------------------------------------------------------- sources
const byId = new Map(usableTopics.map((t) => [t.id, t]));
const sources = [];
for (const page of pages('Notion: Sources')) {
  const status = prop(page, 'Status');
  if (status !== 'Active' && status !== 'Degrading') continue;  // degraded still gets a chance to recover
  const topicIds = (prop(page, 'Topics') || []).map((r) => String(r).replace(/-/g, ''));
  const linked = topicIds.filter((tid) => byId.has(tid));
  if (linked.length === 0) continue;                            // a source nobody listens to is not fetched
  const source = {
    id: id(page),
    name: prop(page, 'Source') || '(unnamed)',
    url: prop(page, 'Address') || '',
    type: norm(prop(page, 'Type')) || 'rss',
    status,
    failures: Number(prop(page, 'Failures in a row')) || 0,
    topicIds: linked,
  };
  if (!source.url) continue;
  sources.push(source);
  for (const tid of linked) byId.get(tid).sourceIds.push(source.id);
}

// A topic with no live sources cannot produce anything today. It is not an error — it is the trigger
// for source discovery, and the daily brief says so in its footer instead of just coming up short.
const orphanTopics = usableTopics.filter((t) => t.sourceIds.length === 0).map((t) => t.name);

return [{
  json: {
    config,
    topics: usableTopics,
    sources,
    warnings: {
      topics_without_criterion: brokenTopics,
      topics_without_sources: orphanTopics,
    },
    counts: {
      topics_active: usableTopics.length,
      sources_active: sources.length,
    },
  },
}];

// [3] Turn the source list into one item per HTTP request. The adapter map is the whole reason a new
// kind of source is one row in Notion plus one entry here, and nothing else in the graph changes.
//
// `lane` decides which branch of the Switch the item takes: xml feeds go through n8n's XML node first,
// json feeds go straight to the normalizer. Add a type -> pick a lane -> map its fields. That is it.
const ADAPTERS = {
  rss: { lane: 'xml' },
  atom: { lane: 'xml' },
  // A YouTube channel has a real RSS feed, which is why "watch this channel" costs nothing extra.
  // Accepts a channel id, a full feed url, or a /channel/<id> link.
  youtube: {
    lane: 'xml',
    url: (u) => (u.includes('feeds/videos.xml')
      ? u
      : `https://www.youtube.com/feeds/videos.xml?channel_id=${(u.match(/(UC[\w-]{20,})/) || [, u])[1]}`),
  },
  // Reddit serves JSON on any listing by appending .json — no API key for read-only use.
  reddit: {
    lane: 'json',
    url: (u) => (u.endsWith('.json') ? u : `${u.replace(/\/$/, '')}/new.json?limit=50`),
  },
  // Hacker News titles are written by whoever submitted the link, not by the article's author, so the
  // keyword filter is weaker here. The normalizer keeps the linked article's domain for that reason.
  hn: { lane: 'xml' },
  json: { lane: 'json' },
  // Reserved: used only when a topic has no healthy sources at all. Not fetched on the normal path.
  web_search: { lane: 'skip' },
};

// Some publishers answer a bare client with 403. A plain, honest user agent is enough for the ones
// that only block empty UAs; the ones behind a real anti-bot wall (Cloudflare) stay unreachable and
// that is what the source health counter is for.
const UA = 'Mozilla/5.0 (compatible; notion-driven-news-brief/1.0; +https://github.com/)';

const { config, sources, topics, warnings, counts } = $input.first().json;

if (config.paused) {
  // Pause in Settings: the run ends here, deliberately and visibly, instead of quietly fetching nothing.
  return [{ json: { skip: true, reason: 'paused', config, topics, warnings, counts } }];
}

const plan = [];
for (const source of sources) {
  const adapter = ADAPTERS[source.type];
  if (!adapter || adapter.lane === 'skip') continue;
  plan.push({
    json: {
      ...source,
      lane: adapter.lane,
      fetch_url: adapter.url ? adapter.url(source.url) : source.url,
      headers: { 'User-Agent': UA, Accept: adapter.lane === 'json' ? 'application/json' : 'application/rss+xml, application/xml, text/xml, */*' },
      // carried along so every downstream node can stay stateless
      _config: config,
      _topics: topics,
      _warnings: warnings,
      _counts: counts,
    },
  });
}

if (plan.length === 0) {
  return [{ json: { skip: true, reason: 'no_sources', config, topics, warnings, counts } }];
}

return plan;

// [5a] Is what came back actually a feed? Runs before the XML node, because the XML node's answer to
// "this is not XML" is to throw and take the whole morning with it.
//
// This is not a theoretical guard. VentureBeat's AI feed stopped being a feed and started serving an
// Astro-rendered HTML page at the same address — no 404, no redirect, just a page. Without this check
// one publisher's redesign ends the brief for everyone.
const res = $input.item.json;

// `neverError` on the HTTP node means a bad status arrives as data rather than as an exception.
const status = Number(res.statusCode ?? res.status ?? 200);
const body = res.data ?? res.body ?? res;
const head = String(typeof body === 'string' ? body : '').slice(0, 400).trim();

if (status >= 400) {
  return { json: { _fetch_failed: true, _fetch_error: `HTTP ${status}`, _is_xml: false } };
}
if (!head) {
  return { json: { _fetch_failed: true, _fetch_error: 'empty response', _is_xml: false } };
}
if (!/^\s*(<\?xml|<rss|<feed|<rdf)/i.test(head)) {
  // Name what it actually is. "not a feed: serves an HTML page" in the source note three weeks later tells
  // you to go find the new address; "parse error" tells you nothing.
  return {
    json: {
      _fetch_failed: true,
      _is_xml: false,
      _fetch_error: /<!doctype html|<html/i.test(head) ? 'not a feed: serves an HTML page' : 'not a feed: unknown format',
    },
  };
}

// Only the payload goes on, under the name the XML node reads. Anything else set here would be lost:
// the XML node replaces the whole item with what it parsed.
return { json: { data: body, _is_xml: true } };

// [5b] Put the source back on the item, AFTER parsing.
//
// Two n8n facts make this its own node. An HTTP Request node replaces the item it was given, and the
// XML node replaces it again with whatever it parsed — so by the time a feed is readable, which source
// it came from is gone. Running once per item lets $('Build fetch plan').item resolve the request this
// response belongs to through n8n's own item pairing.
//
// The same node sits on all three lanes: parsed XML, raw JSON, and the rejects from [5a].
const j = $input.item.json;

let source = {};
try {
  source = $('Build fetch plan').item.json;
} catch {
  // Pairing can be lost if a node in between drops it. Better an item without its source name than a
  // crashed run: [6] counts it under an unknown source and the brief still goes out.
  source = { name: '(source unknown)', type: 'rss', topicIds: [] };
}

if (j._fetch_failed === true) {
  return { json: { _source: source, _fetch_failed: true, _fetch_error: j._fetch_error || 'no answer' } };
}

return { json: { _source: source, _fetch_failed: false, _body: j.data ?? j } };

// [5b] Put the source back on the item, AFTER parsing.
//
// Two n8n facts make this its own node. An HTTP Request node replaces the item it was given, and the
// XML node replaces it again with whatever it parsed — so by the time a feed is readable, which source
// it came from is gone. Running once per item lets $('Build fetch plan').item resolve the request this
// response belongs to through n8n's own item pairing.
//
// The same node sits on all three lanes: parsed XML, raw JSON, and the rejects from [5a].
const j = $input.item.json;

let source = {};
try {
  source = $('Build fetch plan').item.json;
} catch {
  // Pairing can be lost if a node in between drops it. Better an item without its source name than a
  // crashed run: [6] counts it under an unknown source and the brief still goes out.
  source = { name: '(source unknown)', type: 'rss', topicIds: [] };
}

if (j._fetch_failed === true) {
  return { json: { _source: source, _fetch_failed: true, _fetch_error: j._fetch_error || 'no answer' } };
}

return { json: { _source: source, _fetch_failed: false, _body: j.data ?? j } };

// [5b] Put the source back on the item, AFTER parsing.
//
// Two n8n facts make this its own node. An HTTP Request node replaces the item it was given, and the
// XML node replaces it again with whatever it parsed — so by the time a feed is readable, which source
// it came from is gone. Running once per item lets $('Build fetch plan').item resolve the request this
// response belongs to through n8n's own item pairing.
//
// The same node sits on all three lanes: parsed XML, raw JSON, and the rejects from [5a].
const j = $input.item.json;

let source = {};
try {
  source = $('Build fetch plan').item.json;
} catch {
  // Pairing can be lost if a node in between drops it. Better an item without its source name than a
  // crashed run: [6] counts it under an unknown source and the brief still goes out.
  source = { name: '(source unknown)', type: 'rss', topicIds: [] };
}

if (j._fetch_failed === true) {
  return { json: { _source: source, _fetch_failed: true, _fetch_error: j._fetch_error || 'no answer' } };
}

return { json: { _source: source, _fetch_failed: false, _body: j.data ?? j } };

// [5] Everything a source returned becomes the same shape here. Both lanes land in this node: the xml
// lane arrives already parsed by n8n's XML node, the json lane arrives as the API's own object.
// After this node nothing downstream knows or cares what kind of source an item came from.
const SUMMARY_MAX = 600;   // enough for the model to judge, short enough to keep the batch cheap

// Query parameters that identify the campaign, not the article. Stripping them before hashing is what
// makes "the same story shared twice" one row instead of two.
const TRACKING = /^(utm_|fbclid|gclid|mc_cid|mc_eid|ref|ref_src|igshid|_hsenc|_hsmi|source)/i;

function canonicalUrl(raw) {
  try {
    const u = new URL(String(raw).trim());
    u.hash = '';
    u.hostname = u.hostname.replace(/^www\./i, '').toLowerCase();
    u.protocol = 'https:';
    for (const key of [...u.searchParams.keys()]) if (TRACKING.test(key)) u.searchParams.delete(key);
    u.pathname = u.pathname.replace(/\/+$/, '') || '/';
    return u.toString();
  } catch {
    return String(raw || '').trim();
  }
}

// FNV-1a. No crypto import, no dependency, same answer on every n8n version — which matters because
// this hash IS the memory of what was already sent. Change the algorithm and yesterday comes back.
function hash(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

const stripHtml = (s) => String(s || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;|&apos;/gi, "'")
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/\s+/g, ' ')
  .trim();

const text = (v) => {
  if (v === null || v === undefined) return '';
  if (typeof v === 'string') return v;
  if (Array.isArray(v)) return text(v[0]);
  if (typeof v === 'object') return text(v['#text'] ?? v._ ?? v.$t ?? v.href ?? v['@href'] ?? '');
  return String(v);
};

const arr = (v) => (v === null || v === undefined ? [] : Array.isArray(v) ? v : [v]);

function isoDate(v) {
  const raw = text(v);
  if (!raw) return null;
  const dt = DateTime.fromISO(raw, { setZone: true });
  if (dt.isValid) return dt.toUTC().toISO();
  const rfc = DateTime.fromRFC2822(raw, { setZone: true });      // RSS pubDate is RFC-822
  if (rfc.isValid) return rfc.toUTC().toISO();
  const loose = DateTime.fromJSDate(new Date(raw));
  return loose.isValid ? loose.toUTC().toISO() : null;
}

// ---------------------------------------------------------------- per-format readers
function readRss(body) {
  const channel = body?.rss?.channel ?? body?.channel ?? {};
  return arr(channel.item).map((it) => ({
    title: stripHtml(text(it.title)),
    url: text(it.link) || text(it.guid),
    summary: stripHtml(text(it.description) || text(it['content:encoded'])),
    published: isoDate(it.pubDate ?? it.published ?? it['dc:date']),
  }));
}

function readAtom(body) {
  const feed = body?.feed ?? {};
  return arr(feed.entry).map((e) => {
    // Atom puts the address in an attribute; the XML node may expose it as href, @href or $.href.
    const link = arr(e.link).map((l) => text(l.href ?? l['@href'] ?? l?.$?.href ?? l)).find(Boolean);
    return {
      title: stripHtml(text(e.title)),
      url: link || text(e.id),
      summary: stripHtml(text(e.summary) || text(e.content) || text(e['media:group']?.['media:description'])),
      published: isoDate(e.published ?? e.updated),
    };
  });
}

function readReddit(body) {
  return arr(body?.data?.children).map((c) => {
    const d = c.data || {};
    return {
      title: stripHtml(d.title),
      // For a link post the interesting address is the target, not the comment thread.
      url: d.url_overridden_by_dest || d.url || `https://www.reddit.com${d.permalink || ''}`,
      summary: stripHtml(d.selftext || ''),
      published: d.created_utc ? DateTime.fromSeconds(Number(d.created_utc)).toUTC().toISO() : null,
    };
  });
}

// ---------------------------------------------------------------- main
const out = [];
const perSource = {};

for (const item of $input.all()) {
  const j = item.json;
  // The source metadata rides along from [3]; a failed fetch is marked by [4] and carries no body.
  const meta = j._source || j;
  const failed = j._fetch_failed === true;
  const stat = (perSource[meta.name] = perSource[meta.name] || { ok: !failed, items: 0, error: j._fetch_error || null });

  if (failed) continue;

  const body = j._body ?? j.data ?? j;
  let raw = [];
  try {
    if (meta.type === 'reddit') raw = readReddit(body);
    else if (meta.type === 'json') raw = readReddit(body);          // generic JSON uses the same shape by convention
    else if (body?.feed) raw = readAtom(body);                       // atom and youtube
    else raw = readRss(body);                                        // rss and hn
  } catch (e) {
    stat.ok = false;
    stat.error = `parse failed: ${e.message}`;
    continue;
  }

  for (const r of raw) {
    if (!r.title || !r.url) continue;
    const url = canonicalUrl(r.url);
    let domain = '';
    try { domain = new URL(url).hostname; } catch { domain = ''; }
    out.push({
      json: {
        source_id: meta.id,
        source_name: meta.name,
        source_type: meta.type,
        topic_ids: meta.topicIds || [],
        title: r.title,
        url,
        url_hash: hash(url),
        // A Hacker News entry is a pointer, not an article: the domain is often the only clue about
        // what is actually behind it, so it is kept and shown to the model.
        domain,
        summary_raw: (r.summary || '').slice(0, SUMMARY_MAX),
        published_at: r.published,
        _config: meta._config || j._config,
        _topics: meta._topics || j._topics,
      },
    });
    stat.items += 1;
  }
}

if (out.length === 0) {
  return [{ json: { empty: true, per_source: perSource } }];
}

// The per-source tally travels on the first item; [11] folds it into the daily Runs row.
out[0].json._per_source = perSource;
return out;

// [6] Stage one: pure code, no model, five checks in order from cheapest to dearest. Around 180 items
// in, around 40 out — those numbers are what the previous five months looked like, not a target.
//
// Reading the seen-index here but NOT writing it is deliberate: if the run dies before delivery, the
// items it looked at must still be new tomorrow. [12] writes the index only after the brief is sent.
const CLUSTER_SIMILARITY = 0.6;   // share of content words two titles must have in common to be one story
const MIN_TOKEN = 4;              // shorter words carry no signal for clustering

const STOP = new Set([
  'the', 'and', 'for', 'with', 'from', 'that', 'this', 'into', 'your', 'you', 'are', 'was', 'were',
  'its', 'has', 'have', 'will', 'can', 'new', 'now', 'why', 'how', 'what', 'when', 'about', 'after',
  'says', 'said', 'over', 'more', 'than', 'but', 'not', 'all', 'out', 'up', 'his', 'her', 'their',
]);

const items = $input.all().map((i) => i.json).filter((j) => j && j.url);
if (items.length === 0) {
  return [{ json: { empty: true, reason: 'nothing_fetched' } }];
}

const config = items[0]._config || {};
const topics = items[0]._topics || [];
const perSource = items.find((j) => j._per_source)?._per_source || {};
const byTopic = new Map(topics.map((t) => [t.id, t]));

// Seen-index: { hash: 'YYYY-MM-DD' }. Read-only in this node.
const store = $getWorkflowStaticData('global');
const seen = store.seen || {};

const now = DateTime.now();
const counters = {
  fetched: items.length,
  dropped_out_of_window: 0,
  dropped_already_seen: 0,
  dropped_duplicate: 0,
  dropped_minus_signal: 0,
  dropped_no_signal: 0,
  signal_hits: {},
  minus_hits: {},
};

const bump = (bag, key) => { bag[key] = (bag[key] || 0) + 1; };

function tokens(title) {
  return new Set(
    String(title).toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/)
      .filter((w) => w.length >= MIN_TOKEN && !STOP.has(w)),
  );
}

function jaccard(a, b) {
  if (a.size === 0 || b.size === 0) return 0;
  let shared = 0;
  for (const w of a) if (b.has(w)) shared += 1;
  return shared / (a.size + b.size - shared);
}

// ---------------------------------------------------------------- 1 + 2: window and memory
const survivors = [];
for (const it of items) {
  // Widest window among the topics this source serves: a source feeding two topics must not be cut
  // by the stricter one before the looser topic ever sees the item.
  const windows = (it.topic_ids || []).map((id) => byTopic.get(id)?.windowHours).filter(Boolean);
  const windowHours = windows.length ? Math.max(...windows) : 24;

  if (it.published_at) {
    const age = now.diff(DateTime.fromISO(it.published_at), 'hours').hours;
    if (!(age <= windowHours)) { counters.dropped_out_of_window += 1; continue; }
  }
  // No date in the feed is not a reason to drop: some feeds simply do not publish one. The item goes
  // through and the model sees it without a date.

  if (seen[it.url_hash]) { counters.dropped_already_seen += 1; continue; }
  survivors.push({ ...it, _tokens: tokens(it.title) });
}

// ---------------------------------------------------------------- 3: one story, many sources
const clusters = [];
for (const it of survivors) {
  const home = clusters.find((c) => jaccard(c.tokens, it._tokens) >= CLUSTER_SIMILARITY);
  if (home) {
    home.members.push(it);
    // Keep the copy from the source that is closest to the original: a publisher over an aggregator.
    if (home.lead.source_type === 'hn' && it.source_type !== 'hn') home.lead = it;
    counters.dropped_duplicate += 1;
  } else {
    clusters.push({ tokens: it._tokens, lead: it, members: [it] });
  }
}

// ---------------------------------------------------------------- 4 + 5: minus-signals and signals
const candidates = [];
for (const c of clusters) {
  const it = c.lead;
  const haystack = `${it.title} ${it.summary_raw} ${it.domain}`.toLowerCase();
  const itemTopics = (it.topic_ids || []).map((id) => byTopic.get(id)).filter(Boolean);

  // A minus-signal from ANY topic this item could belong to kills it. Muting is absolute by design:
  // "I never want to see this" should not depend on which topic happened to catch it.
  const muted = itemTopics.flatMap((t) => t.minusSignals).find((w) => haystack.includes(w));
  if (muted) { counters.dropped_minus_signal += 1; bump(counters.minus_hits, muted); continue; }

  // A topic with an empty Signals list has its keyword filter switched off on purpose: it accepts
  // everything in the window and pays the model to decide.
  const matched = [];
  let openTopic = false;
  for (const t of itemTopics) {
    if (!t.keywordFilter) { openTopic = true; continue; }
    for (const s of t.signals) {
      if (haystack.includes(s)) { matched.push(s); bump(counters.signal_hits, s); }
    }
  }
  if (!openTopic && matched.length === 0) { counters.dropped_no_signal += 1; continue; }

  candidates.push({
    ...it,
    _tokens: undefined,
    duplicates: c.members.length,
    duplicate_sources: [...new Set(c.members.map((m) => m.source_name))],
    matched_signals: [...new Set(matched)],
    candidate_topic_ids: itemTopics.map((t) => t.id),
  });
}

// ---------------------------------------------------------------- budget ceiling (money, not count)
// This is the only number that can cut the list, and it never decides what is worth reading — it
// decides how much we are willing to pay to find out. When it bites, the brief says so out loud.
const PRIORITY_ORDER = { '🔥 High': 0, '⚡ Medium': 1, '💤 Low': 2 };
candidates.sort((a, b) => {
  const pa = Math.min(...a.candidate_topic_ids.map((id) => PRIORITY_ORDER[byTopic.get(id)?.priority] ?? 1));
  const pb = Math.min(...b.candidate_topic_ids.map((id) => PRIORITY_ORDER[byTopic.get(id)?.priority] ?? 1));
  if (pa !== pb) return pa - pb;
  return String(b.published_at || '').localeCompare(String(a.published_at || ''));
});

const ceiling = Number(config.budgetCeiling) || 250;
const budgetHit = candidates.length > ceiling;
const shortlist = budgetHit ? candidates.slice(0, ceiling) : candidates;

counters.considered = items.length;
counters.to_model = shortlist.length;
counters.dropped_by_rule = items.length - shortlist.length;

if (shortlist.length === 0) {
  return [{ json: { empty: true, reason: 'nothing_survived_stage1', counters, per_source: perSource, config, topics } }];
}

return shortlist.map((json, i) => ({
  json: {
    ...json,
    _first: i === 0,
    ...(i === 0 ? {
      _counters: counters,
      _per_source: perSource,
      _budget: { ceiling, hit: budgetHit, wanted: candidates.length },
    } : {}),
  },
}));

// [7] Pack the shortlist for the model. One call per chunk of items, with every active topic's
// criterion inside it — not one call per item-and-topic pair, which would multiply the bill by the
// number of topics and let the same article arrive twice under two headings.
//
// Chunking also stops the topic block from being re-sent with every single article: at six topics
// that block is the bulk of the prompt, so sending it once per eight items instead of once per item
// is most of the cost saved.
const CHUNK = 8;              // items per model call. Smaller = safer JSON, larger = cheaper.
const TITLE_MAX = 200;
const SUMMARY_MAX = 400;      // the model judges relevance, not quality: the opening is enough

const items = $input.all().map((i) => i.json);
const head = items.find((j) => j._counters) || items[0] || {};
const topics = head._topics || items[0]?._topics || [];
const config = head._config || items[0]?._config || {};

// The topic block is written once and reused. Criteria are the user's own words from Notion — they are
// data, not instructions: the prompt frames them as descriptions to match against, never as commands.
//
// Topics are labelled t1..tN rather than by their Notion id. A 32-character hex string is something
// models copy wrong or quietly give up on: the first live run handed over real ids and got six verdicts
// back, every one with an empty topic and a reason that plainly described a match. Short labels, mapped
// back in code, removed the failure completely.
const topicBlock = topics.map((t, i) => `- id: t${i + 1}\n  name: ${t.name}\n  wants: ${t.criterion}`).join('\n');
const topicMap = topics.map((t) => t.id);

// The prompt is told the language by name, not by code: a model writes better Ukrainian when
// asked for "Ukrainian" than when handed "uk".
const LANGS = {'en': 'English', 'uk': 'Ukrainian', 'de': 'German', 'fr': 'French', 'es': 'Spanish', 'pl': 'Polish'};
const language = LANGS[(config.lang || 'en')] || 'English';

const chunks = [];
for (let i = 0; i < items.length; i += CHUNK) {
  const slice = items.slice(i, i + CHUNK);
  const articles = slice.map((it, n) => [
    `#${n}`,
    `title: ${String(it.title).slice(0, TITLE_MAX)}`,
    it.domain ? `domain: ${it.domain}` : null,
    it.published_at ? `published: ${it.published_at}` : null,
    it.summary_raw ? `excerpt: ${String(it.summary_raw).slice(0, SUMMARY_MAX)}` : null,
  ].filter(Boolean).join('\n')).join('\n\n');

  chunks.push({
    json: {
      chunk_index: chunks.length,
      // keys back to the real items; the model only ever sees #0..#7
      item_hashes: slice.map((it) => it.url_hash),
      topic_map: topicMap,
      prompt_topics: topicBlock,
      prompt_articles: articles,
      expected: slice.length,
      prompt_language: language,
      _config: config,
      _topics: topics,
      ...(chunks.length === 0 ? {
        _counters: head._counters,
        _per_source: head._per_source,
        _budget: head._budget,
        _all_items: items,
      } : {}),
    },
  });
}

return chunks;

