// [12] Build the message and the archive page from the same data.
//
// Everything here that looks like a style rule is one: they came out of five months of the routine
// this case replaces, and they are the difference between a digest someone reads and one they mute.
const MAX_TELEGRAM = 4096;     // hard platform limit; the page link is what makes it irrelevant

// The only words the system writes itself. Everything else in a brief comes from the model, in the
// language the reader set. Adding a language is a row here, not a change anywhere else.
const STRINGS = {
  en: { brief: 'Brief', nothing: 'Nothing cleared the bar today.', read: 'read', included: 'included',
        silent: 'sources silent', ceiling: 'of', ceilingTail: 'considered — budget ceiling',
        noVerdict: 'no verdict', alsoIn: 'also in', open: 'Read the original',
        full: 'full brief ↗', judged: 'reached scoring, best below the threshold', more: 'more on the page' },
  uk: { brief: 'Бриф', nothing: 'Сьогодні нічого не перетнуло поріг.', read: 'прочитано', included: 'включено',
        silent: 'джерела мовчать', ceiling: 'з', ceilingTail: 'розглянуто — стеля бюджету',
        noVerdict: 'без вердикту', alsoIn: 'також у', open: 'Читати оригінал',
        full: 'повний бриф ↗', judged: 'дійшло до оцінки, найкраще нижче порога', more: 'далі на сторінці брифу' },
};
const PRIORITY_ORDER = { '🔥 High': 0, '⚡ Medium': 1, '💤 Low': 2 };

const first = $input.first().json;
// The digest payload rides on the first writer request, not on the chain's answer.
let head = first;
try {
  head = $('Build writer input').all().map((i) => i.json).find((j) => j._included || j.nothing_today) || first;
} catch { head = first; }
const included = head._included || first.included || [];
const counters = head._counters || head.counters || first.counters || {};
const config = head._config || head.config || first.config || {};
const perSource = head._per_source || head.per_source || first.per_source || {};
const budget = head._budget || head.budget || first.budget || { hit: false };
const buckets = head._buckets || head.score_buckets || first.score_buckets || {};
const problems = [...(head._problems || head.problems || first.problems || [])];

const publicBase = String(config.publicBase || 'http://localhost:5678').replace(/\/$/, '');

// Click tracking needs an address the outside world can reach. On localhost it is worse than useless:
// Telegram refuses to turn a localhost href into a link at all, so the reader gets the words
// "Читати оригінал" as plain text and no way to open anything. When the address is not public the
// wrapper is dropped and links point straight at the article. The counter is lost, the reading is not.
const trackable = !/^https?:\/\/(localhost|127\.|0\.0\.0\.0|\[::1\]|192\.168\.|10\.)/i.test(publicBase);
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const date = DateTime.now().toFormat('dd.MM.yyyy');
const S = STRINGS[config.lang] || STRINGS.en;

// ---------------------------------------------------------------- merge the written text back in
// The writer returns Ukrainian title, two or three sentences, and the "why it matters" line. When it
// fails for an item we still ship the item with its original title: a missing paragraph is a smaller
// loss than a missing article.
// Same as in [9]: the chain answers with its output only, so which article each #number refers to is
// read back from the node that built the request, matched by position.
const written = new Map();
const writerRequests = (() => { try { return $('Build writer input').all().map((i) => i.json); } catch { return []; } })();
const answers = $input.all();
for (let ci = 0; ci < answers.length; ci++) {
  let v = answers[ci].json?.output ?? answers[ci].json?.text ?? answers[ci].json;
  if (typeof v === 'string') { try { v = JSON.parse(v.match(/\{[\s\S]*\}/)?.[0] || v); } catch { v = null; } }
  const list = v?.items ?? v?.results ?? (Array.isArray(v) ? v : null);
  const hashes = (writerRequests[ci] || {}).item_hashes || [];
  if (!Array.isArray(list)) continue;
  for (const w of list) {
    const idx = Number(w.i ?? w.index);
    if (!Number.isInteger(idx) || !hashes[idx]) continue;
    written.set(hashes[idx], {
      title: String(w.title_uk || w.title || '').trim(),
      summary: String(w.summary_uk || w.summary || '').trim(),
      // "💡 Чому це важливо" is printed only when the model had something real to say. A forced line
      // here is worse than no line: it teaches the reader to skip the section.
      why: String(w.why || w.why_it_matters || '').trim(),
    });
  }
}

// ---------------------------------------------------------------- nothing today
if (included.length === 0) {
  const text = `🌅 <b>Бриф ${date}</b>\n\nСьогодні нічого не перетнуло поріг.\n\n<i>${counters.considered || 0} прочитано · 0 включено</i>`;
  return [{ json: { nothing_today: true, telegram_text: text, page_title: `🌅 Бриф ${date}`,
    page_markdown: `Сьогодні нічого не перетнуло поріг.\n\n${counters.considered || 0} прочитано · 0 включено.`,
    items: [], counters, config, per_source: perSource, budget, buckets, problems } }];
}

// ---------------------------------------------------------------- group by topic, sort by score
const groups = new Map();
for (const it of included) {
  if (!groups.has(it.topic_id)) groups.set(it.topic_id, { name: it.topic_name, priority: it.topic_priority, items: [] });
  groups.get(it.topic_id).items.push(it);
}
const ordered = [...groups.values()].sort(
  (a, b) => (PRIORITY_ORDER[a.priority] ?? 1) - (PRIORITY_ORDER[b.priority] ?? 1) || a.name.localeCompare(b.name),
);
for (const g of ordered) g.items.sort((a, b) => b.score - a.score);
const showHeadings = ordered.length > 1;

// ---------------------------------------------------------------- footer
// The footer is where the system admits things. Everything that could make the brief quietly thinner
// than it should be gets a line here, so "нічого цікавого" never hides a broken source or a ceiling.
const footer = [`${counters.considered || 0} ${S.read} · ${included.length} ${S.included}`];
const silent = Object.entries(perSource).filter(([, s]) => !s.ok).map(([name]) => name);
if (silent.length) footer.push(`${S.silent}: ${silent.join(', ')}`);
if (budget.hit) footer.push(`${budget.ceiling} ${S.ceiling} ${budget.wanted} ${S.ceilingTail}`);
if (counters.no_verdict) footer.push(`${S.noVerdict}: ${counters.no_verdict}`);
if (problems.length) footer.push(problems.join('; '));

// ---------------------------------------------------------------- render
const tg = [`🌅 <b>${S.brief} ${date}</b>`];
const md = [];
const rows = [];
let n = 0;

for (const g of ordered) {
  if (showHeadings) { tg.push('', `<b>${esc(g.name)}</b>`); md.push(`## ${g.name}`); }
  for (const it of g.items) {
    n += 1;
    const w = written.get(it.url_hash) || {};
    const title = w.title || it.title;
    const summary = w.summary || '';
    const track = trackable ? `${publicBase}/webhook/r?i=${encodeURIComponent(it.url_hash)}` : it.url;

    const block = [`${n}. <b>${esc(title)}</b>`];
    if (summary) block.push(esc(summary));
    if (w.why) block.push(`💡 <i>${esc(w.why)}</i>`);
    if (it.duplicates > 1) block.push(`<i>${S.alsoIn}: ${esc(it.duplicate_sources.filter((s) => s !== it.source_name).join(', '))}</i>`);
    block.push(`🔗 <a href="${esc(track)}">${S.open}</a>`);
    tg.push('', block.join('\n'));

    md.push(`### ${n}. ${title}`);
    if (summary) md.push(summary);
    if (w.why) md.push(`💡 ${w.why}`);
    md.push(`${it.source_name} · ${it.score} · ${it.reason}`);
    md.push(`[${S.open}](${it.url})`);

    rows.push({
      hash: it.url_hash, title, url: it.url, source_id: it.source_id, topic_id: it.topic_id,
      published_at: it.published_at, score: it.score, reason: it.reason, duplicates: it.duplicates || 1,
    });
  }
}

const pageTitle = `🌅 ${S.brief} ${date}`;
tg.push('', `<i>${esc(footer.join(' · '))}</i>`);
md.push('---', footer.join(' · '));

let telegramText = tg.join('\n');
if (telegramText.length > MAX_TELEGRAM) {
  // Should not happen now that the page carries the long form, but truncating loudly beats a silent
  // Telegram 400 that loses the whole morning.
  telegramText = `${telegramText.slice(0, MAX_TELEGRAM - 120)}\n\n<i>…далі на сторінці брифу</i>`;
  problems.push('telegram limit reached, message truncated');
}

return [{
  json: {
    nothing_today: false,
    telegram_text: telegramText,
    page_title: pageTitle,
    page_markdown: md.join('\n\n'),
    items: rows,
    counters: { ...counters, included: included.length },
    // Not in the brief's own footer: a line every single morning about infrastructure the reader
    // already knows about is nagging. It belongs in the run row, where it is looked up when wanted.
    tracking_enabled: trackable,
    config, per_source: perSource, budget, buckets, problems,
  },
}];

// [14] Notion payloads for the archive: one page per brief, one row per item that shipped.
//
// Only what was sent is written. The ~170 articles the filter threw out leave their mark as numbers in
// the daily Runs row, not as rows here — that is the difference between an archive a person opens and
// a table that is unusable by spring.
const d = $input.first().json;
const date = DateTime.now();
const iso = date.toISODate();

const rich = (s) => (s ? [{ type: 'text', text: { content: String(s).slice(0, 2000) } }] : []);
const rel = (id) => (id ? [{ id: String(id) }] : []);

// The brief page is created first: every item row links back to it, so the archive reads both ways —
// from a day to its items, and from an item to the morning it arrived in.
const briefPage = {
  properties: {
    'Brief': { title: rich(d.page_title) },
    'Date': { date: { start: iso } },
    'Considered': { number: Number(d.counters?.considered || 0) },
    'Included': { number: Number(d.items?.length || 0) },
  },
  markdown: d.page_markdown,
};

const rows = (d.items || []).map((it) => ({
  properties: {
    'Title': { title: rich(it.title) },
    'Link': { url: it.url || null },
    'Hash': { rich_text: rich(it.hash) },
    'Published': it.published_at ? { date: { start: it.published_at } } : { date: null },
    'Brief date': { date: { start: iso } },
    'Score': { number: Number(it.score) || 0 },
    'Reason': { rich_text: rich(it.reason) },
    'Duplicates': { number: Number(it.duplicates) || 1 },
    'Source': { relation: rel(it.source_id) },
    'Topic': { relation: rel(it.topic_id) },
    // 'Brief' is filled by the next node once the page id exists.
  },
  _hash: it.hash,
}));

return [{ json: { ...d, brief_page: briefPage, feed_rows: rows, run_date: iso } }];

// [15] Fan the archive rows out, one per item, now that the brief page exists and can be linked to.
//
// The brief page is created first on purpose: every row points back at the morning it arrived in, so
// the archive reads both ways — a day to its items, an item to its day.
const created = $input.first().json;              // the Notion response for the brief page
const source = $('Build Notion rows').first().json;
const briefId = created.id || null;

const rows = source.feed_rows || [];
if (rows.length === 0) {
  return [{ json: { ...source, brief_page_id: briefId, no_rows: true } }];
}

return rows.map((row, i) => ({
  json: {
    properties: {
      ...row.properties,
      ...(briefId ? { 'Brief': { relation: [{ id: briefId }] } } : {}),
    },
    _hash: row._hash,
    _brief_page_id: briefId,
    // carried on the first item so the nodes after the loop still have the whole picture
    ...(i === 0 ? { _digest: source } : {}),
  },
}));

// [16] Write the seen-index — and only now, after the brief has actually been delivered.
//
// This node is the reason a crashed run costs nothing. Everything upstream is read-only against the
// index: if the model times out, if Telegram is down, if Notion rejects a write, tomorrow's run sees
// the same articles as new and tries again. The index moves forward only when a human got the brief.
// NOT $input: the node before this one is the Telegram send, and a messenger node replaces the item
// with the API's answer. Reading the input here meant `items` was always empty, so nothing was ever
// marked as seen and every article would have come back the next morning — the exact failure this
// index exists to prevent, and silent enough to survive a week unnoticed.
const d = $('Build Notion rows').first().json;
const store = $getWorkflowStaticData('global');
const today = DateTime.now();
const iso = today.toISODate();

store.seen = store.seen || {};

// Mark what shipped. Only these: an article the filter rejected is not "seen", it is "not wanted
// today" — tomorrow it may match a topic the user edits tonight.
let added = 0;
for (const it of d.items || []) {
  if (!it.hash) continue;
  if (!store.seen[it.hash]) added += 1;
  store.seen[it.hash] = iso;
}

// Rolling window. Hashes are tiny, but unbounded growth in workflow static data is a slow leak that
// would surface months later as a workflow that will not save.
const keepDays = Number(d.config?.memoryDays) || 30;
const cutoff = today.minus({ days: keepDays }).toISODate();
let pruned = 0;
for (const [hash, when] of Object.entries(store.seen)) {
  if (String(when) < cutoff) { delete store.seen[hash]; pruned += 1; }
}

store.last_run = { date: iso, included: (d.items || []).length, considered: d.counters?.considered || 0 };

return [{
  json: {
    ...d,
    seen_index: { added, pruned, size: Object.keys(store.seen).length, window_days: keepDays },
  },
}];

// [17] One row per day. This is where the metrics come from — precision, dead keywords, which source
// actually earns its place — without keeping a row for every article the filter ever looked at.
const d = $input.first().json;
const c = d.counters || {};
const started = d.started_at ? DateTime.fromISO(d.started_at) : null;

// Per source: did it answer, how much did it bring, how much of that survived to the brief. A source
// that answers every morning and has contributed nothing in a month is visible here and nowhere else.
const included = d.items || [];
const perSource = {};
for (const [name, s] of Object.entries(d.per_source || {})) {
  perSource[name] = { ok: !!s.ok, items: Number(s.items || 0), included: 0 };
  if (s.error) perSource[name].error = String(s.error).slice(0, 200);
}
for (const it of included) {
  const name = it.source_name || (d.items_by_source || {})[it.hash];
  if (name && perSource[name]) perSource[name].included += 1;
}

// Signals that fired and signals that never do. A keyword with a zero here for weeks is either dead
// vocabulary or a topic that has drifted — both worth knowing, neither visible any other way.
const signals = {
  hits: c.signal_hits || {},
  muted: c.minus_hits || {},
  score_buckets: d.buckets || {},
};

const errors = [];
if (d.budget?.hit) errors.push(`budget ceiling ${d.budget.ceiling} of ${d.budget.wanted} candidates`);
if (c.no_verdict) errors.push(`${c.no_verdict} items came back without a verdict`);
for (const [name, s] of Object.entries(d.per_source || {})) if (!s.ok) errors.push(`${name}: ${s.error || 'no answer'}`);
for (const p of d.problems || []) errors.push(String(p));
if (d.tracking_enabled === false) errors.push('links not wrapped: the n8n address is not public, click tracking off');
for (const t of d.warnings?.topics_without_sources || []) errors.push(`topic without live sources: ${t}`);
for (const t of d.warnings?.topics_without_criterion || []) errors.push(`topic without a criterion, skipped: ${t}`);

return [{
  json: {
    ...d,
    run_row: {
      properties: {
        'Date': { title: [{ type: 'text', text: { content: d.run_date || DateTime.now().toISODate() } }] },
        'Considered': { number: Number(c.considered || 0) },
        'Dropped by rule': { number: Number(c.dropped_by_rule || 0) },
        'Dropped by model': { number: Number(c.dropped_below_threshold || 0) },
        'Included': { number: included.length },
        'Sources JSON': { rich_text: [{ type: 'text', text: { content: JSON.stringify(perSource).slice(0, 2000) } }] },
        'Signals JSON': { rich_text: [{ type: 'text', text: { content: JSON.stringify(signals).slice(0, 2000) } }] },
        'Errors': { rich_text: [{ type: 'text', text: { content: (errors.join(' · ') || '—').slice(0, 2000) } }] },
        'Duration': { number: started ? Math.round(DateTime.now().diff(started, 'seconds').seconds) : 0 },
      },
    },
  },
}];

// [18] Source health. The answer to the worst failure mode this kind of system has: a feed quietly
// stops answering, the brief gets thinner, and it reads like "not much happened today" for weeks.
//
// A source never dies silently here. It walks through states the user can see, and the day it starts
// failing the brief says so in its own footer.
const DEGRADE_AT = 3;    // consecutive failures before the source is marked as degrading
const RETIRE_AT = 7;     // ...and before it is retired and discovery is offered for its topics

const d = $input.first().json;
const perSource = d.per_source || {};

// The source list lives where it was read, not in the digest: everything between here and [2] is
// about articles, and dragging the whole source table through it would be carrying luggage for the
// sake of one node.
let sources = [];
let topics = [];
try {
  const cfg = $('Load config').first().json;
  sources = cfg.sources || [];
  topics = cfg.topics || [];
} catch { sources = []; }
const byName = new Map(sources.map((s) => [s.name, s]));
const iso = DateTime.now().toISODate();

const updates = [];
for (const [name, stat] of Object.entries(perSource)) {
  const source = byName.get(name);
  if (!source) continue;

  if (stat.ok) {
    // Recovery is a state change too: a source that answers again goes back to Active from Degrading,
    // and the counter resets. Otherwise one bad week would slowly retire a perfectly good feed.
    if (source.failures > 0 || source.status !== 'Active') {
      updates.push({
        page_id: source.id,
        properties: {
          'Last success': { date: { start: iso } },
          'Failures in a row': { number: 0 },
          'Status': { select: { name: 'Active' } },
        },
        _log: `${name}: recovered`,
      });
    } else {
      updates.push({
        page_id: source.id,
        properties: { 'Last success': { date: { start: iso } } },
        _log: null,
      });
    }
    continue;
  }

  const failures = Number(source.failures || 0) + 1;
  let status = source.status;
  let log = null;
  if (failures >= RETIRE_AT) {
    status = 'Retired';
    log = `${name}: retired after ${failures} failed runs`;
  } else if (failures >= DEGRADE_AT) {
    status = 'Degrading';
    log = `${name}: silent for ${failures} runs`;
  }

  updates.push({
    page_id: source.id,
    properties: {
      'Failures in a row': { number: failures },
      'Status': { select: { name: status } },
      'Note': { rich_text: [{ type: 'text', text: {
        content: `${iso}: ${String(stat.error || 'no answer').slice(0, 300)}`,
      } }] },
    },
    _log: log,
  });
}

// Topics whose sources all died. This is the trigger for discovery: the system noticed the hole before
// the user did, and says so rather than serving an empty section.
const retiredIds = new Set(updates.filter((u) => u.properties['Status']?.select?.name === 'Retired').map((u) => u.page_id));
const orphaned = (topics || [])
  .filter((t) => t.sourceIds?.length && t.sourceIds.every((id) => retiredIds.has(id)))
  .map((t) => t.name);

return [{ json: { ...d, source_updates: updates, health_notes: updates.map((u) => u._log).filter(Boolean), orphaned_topics: orphaned } }];

// [19] One item per source whose row needs touching: a success date, a failure counter, a status
// change. Sources that neither succeeded nor failed this run are not in the list and are left alone.
const d = $input.first().json;
const updates = d.source_updates || [];

// Nothing to update means nothing goes downstream. Returning a placeholder item would send the next
// node a PATCH to /pages/undefined, which answers 400 and looks like a broken payload rather than an
// empty list — an hour of reading the wrong thing.
if (updates.length === 0) {
  return [];
}

return updates.map((u, i) => ({
  json: {
    page_id: u.page_id,
    properties: u.properties,
    ...(i === 0 ? { _health_notes: d.health_notes || [], _orphaned: d.orphaned_topics || [] } : {}),
  },
}));

// [20] The webhook does three jobs, told apart by what arrived. It is one entry point because n8n
// activates one webhook path per workflow, and because all three are the same shape of work: a tap
// arrives, a row changes, the person gets on with their day.
//
//   /webhook/r?i=<hash>   a link in the brief was opened  -> record the click, redirect to the article
//   callback  miss:<hash> the weekly review marked an item as noise
//   callback  src:<id>    a proposed source was approved
//
// Nothing here trusts what arrived: a hash is looked up, never used to build a redirect, and the
// target address is read from the archive row. A crafted link cannot turn this into an open redirect.
const req = $input.first().json;
const query = req.query || {};
const body = req.body || {};

const callback = body.callback_query || null;
const data = String(callback?.data || '').trim();
const hash = String(query.i || query.hash || '').trim();

function out(kind, extra) {
  return [{ json: { kind, ...extra } }];
}

// ---------------------------------------------------------------- 1. a click on an article link
if (hash) {
  // Only the shape is validated here; [21] resolves it against Feed and takes the address from the
  // stored row. An unknown hash lands on the brief archive rather than anywhere a stranger chose.
  const clean = /^[0-9a-f]{8}$/.test(hash) ? hash : '';
  return out('click', { hash: clean, valid: !!clean });
}

// ---------------------------------------------------------------- 2 and 3. a button in Telegram
if (data) {
  const [verb, arg] = data.split(':');
  const chatId = callback?.message?.chat?.id;
  const callbackId = callback?.id;

  if (verb === 'miss' || verb === 'miss') {
    return out('verdict', { hash: String(arg || '').trim(), verdict: 'miss', chat_id: chatId, callback_id: callbackId, toast: 'Marked as a miss' });
  }
  if (verb === 'save') {
    return out('verdict', { hash: String(arg || '').trim(), verdict: '📌 saved', chat_id: chatId, callback_id: callbackId, toast: 'Saved' });
  }
  if (verb === 'src') {
    return out('approve_source', { page_id: String(arg || '').trim(), chat_id: chatId, callback_id: callbackId, toast: 'Source switched on' });
  }
  return out('unknown', { data, callback_id: callbackId, toast: '' });
}

// Telegram retries a callback it thinks failed, so anything unrecognised still answers 200 and stops.
return out('ignored', {});

// [22] A link in the brief was opened. Find the row, note the time, and hand back where to send the
// reader — from the stored row, never from the request.
//
// This is the one node in the workflow that a stranger can reach, so it is written as if someone will
// try: the address always comes out of the archive, so a crafted ?i= cannot turn this into an open
// redirect to somewhere else. The worst a bad hash can do is land on the brief archive.
// Where an unknown hash lands. Deliberately somewhere harmless and constant.
const FALLBACK = 'https://www.notion.so';

const route = $('Route webhook').first().json;
const found = ($input.first().json.results || [])[0];

if (!found) {
  // Unknown hash: still a 302, still somewhere harmless, and it is counted rather than hidden.
  return [{ json: { page_id: null, target: FALLBACK, matched: false, hash: route.hash || null, properties: {} } }];
}

const url = found.properties?.['Link']?.url;
const alreadyOpened = found.properties?.['Opened']?.date?.start;

// Only http(s) is followed. A feed that ever hands us a javascript: or data: address does not get to
// pass it on to the reader's browser.
const safe = typeof url === 'string' && /^https?:\/\//i.test(url) ? url : FALLBACK;

return [{
  json: {
    page_id: found.id,
    target: safe,
    matched: true,
    hash: route.hash || null,
    // First open wins. Re-reading an article a week later should not rewrite when it first landed.
    properties: alreadyOpened ? {} : { 'Opened': { date: { start: DateTime.now().toISO() } } },
    already_opened: !!alreadyOpened,
  },
}];

// [31] Source discovery, step one: which topics are asking, and what do they already have.
//
// Runs every quarter of an hour against one cheap Notion query. A topic asks either by having its
// `Find sources` box ticked, or by having no live sources at all — the system noticing a hole
// before the person does.
const MAX_CANDIDATES = 8;

function pages(nodeName) {
  const out = [];
  for (const item of $(nodeName).all()) {
    const j = item.json || {};
    if (Array.isArray(j.results)) out.push(...j.results);
    else if (j.id || j.properties) out.push(j);
  }
  return out;
}

function prop(page, name) {
  const p = (page.properties || {})[name];
  if (!p) return null;
  switch (p.type) {
    case 'title': return (p.title || []).map((t) => t.plain_text).join('');
    case 'rich_text': return (p.rich_text || []).map((t) => t.plain_text).join('');
    case 'select': return p.select ? p.select.name : null;
    case 'multi_select': return (p.multi_select || []).map((o) => o.name);
    case 'checkbox': return p.checkbox;
    case 'url': return p.url;
    case 'relation': return (p.relation || []).map((r) => r.id);
    default: return p[p.type] ?? null;
  }
}

const id = (p) => String(p.id || '').replace(/-/g, '');

// What each topic already reads, so the model does not spend its answer proposing what is there.
const urlsByTopic = new Map();
const liveCount = new Map();
for (const s of pages('Notion: Sources (discovery)')) {
  const status = prop(s, 'Status');
  const url = prop(s, 'Address');
  for (const rel of prop(s, 'Topics') || []) {
    const tid = String(rel).replace(/-/g, '');
    if (!urlsByTopic.has(tid)) urlsByTopic.set(tid, []);
    if (url) urlsByTopic.get(tid).push(url);
    if (status === 'Active') liveCount.set(tid, (liveCount.get(tid) || 0) + 1);
  }
}

// The report is written in the reader's language, like the brief itself.
let settingsLang = 'en';
try {
  for (const r of pages('Notion: Settings (discovery)')) {
    const k = String(prop(r, 'Key') || '').trim().toLowerCase();
    if (k === 'brief language') settingsLang = String(prop(r, 'Value') || 'en').trim().toLowerCase().slice(0, 2);
  }
} catch { settingsLang = 'en'; }

const out = [];
for (const t of pages('Notion: Topics (discovery)')) {
  if (prop(t, 'Status') !== 'Active') continue;
  const tid = id(t);
  const asked = prop(t, 'Find sources') === true;
  const starving = (liveCount.get(tid) || 0) === 0;
  if (!asked && !starving) continue;

  const criterion = (prop(t, 'Criterion') || '').trim();
  if (!criterion) continue;   // nothing to search for; [6] already names such topics in the run row

  out.push({
    json: {
      topic_id: tid,
      topic_page_id: t.id,
      topic_name: prop(t, 'Topic'),
      asked_explicitly: asked,
      prompt_topic: `name: ${prop(t, 'Topic')}\nwants: ${criterion}`,
      prompt_languages: (prop(t, 'Languages') || ['en']).join(', '),
      prompt_existing: (urlsByTopic.get(tid) || []).join('\n') || '(none yet)',
      max_candidates: MAX_CANDIDATES,
      lang: settingsLang,
    },
  });
}

return out;

