{
  "type": "object",
  "properties": {
    "candidates": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "The publication's name."
          },
          "url": {
            "type": "string",
            "description": "The FEED address, not the site's home page. Usually ends in /feed, /rss, /atom.xml or similar."
          },
          "type": {
            "type": "string",
            "enum": [
              "rss",
              "atom",
              "youtube",
              "reddit",
              "hn",
              "json"
            ]
          },
          "why": {
            "type": "string",
            "maxLength": 200,
            "description": "One line on why this fits the topic, in the reader s language."
          }
        },
        "required": [
          "name",
          "url",
          "type",
          "why"
        ],
        "additionalProperties": false
      }
    }
  },
  "required": [
    "candidates"
  ],
  "additionalProperties": false
}

parameters.jsCode:
// [32] The model's candidates become one item each, ready to be fetched.
//
// Nothing here trusts the answer. Addresses are only shape-checked so the fetch has something to try;
// whether the thing at the other end is a real, living feed is decided in [34] by actually reading it.
const answers = $input.all();
const requests = (() => { try { return $('Build discovery input').all().map((i) => i.json); } catch { return []; } })();

const out = [];
for (let ci = 0; ci < answers.length; ci++) {
  const req = requests[ci] || {};
  let v = answers[ci].json?.output ?? answers[ci].json?.text ?? answers[ci].json;
  if (typeof v === 'string') { try { v = JSON.parse(v.match(/\{[\s\S]*\}/)?.[0] || v); } catch { v = null; } }
  const list = v?.candidates ?? v?.sources ?? (Array.isArray(v) ? v : null);
  if (!Array.isArray(list)) continue;

  const seen = new Set((req.prompt_existing || '').split('\n').map((u) => u.trim()).filter(Boolean));

  for (const c of list.slice(0, req.max_candidates || 8)) {
    const url = String(c.url || '').trim();
    // Only http(s) is ever fetched. A model that answers with a file: or javascript: address gets
    // nothing, silently, rather than handing the workflow something odd to open.
    if (!/^https?:\/\/\S+$/i.test(url)) continue;
    if (seen.has(url)) continue;

    const type = ['rss', 'atom', 'youtube', 'reddit', 'hn', 'json'].includes(String(c.type || '').toLowerCase())
      ? String(c.type).toLowerCase() : 'rss';

    out.push({
      json: {
        _candidate: {
          name: String(c.name || '').trim().slice(0, 80) || '(unnamed)',
          url,
          type,
          why: String(c.why || c.reason || '').trim().slice(0, 200),
          topic_id: req.topic_id,
          topic_page_id: req.topic_page_id,
          topic_name: req.topic_name,
        },
        fetch_url: url,
      },
    });
  }
}

return out;

// [33] Source discovery, step two: the part that makes the first part safe.
//
// Every candidate has just been fetched for real. Here it either parses, is alive, and is new — or it
// does not reach the database at all. The model proposes, this code checks, the person approves. That
// order is the whole trust story of the case, and it is worth saying out loud in the README.
const MIN_ITEMS = 3;            // a feed with one entry is a landing page, not a source
const MAX_STALE_DAYS = 14;      // last entry older than this means the feed is abandoned
const now = DateTime.now();

// The fetch replaced each item with its response, so the candidate it belongs to is read back from
// the node that proposed it, by position — same pairing problem as everywhere else in this workflow.
const proposals = (() => { try { return $('Parse proposals').all().map((i) => i.json._candidate || {}); } catch { return []; } })();

const results = [];
const all = $input.all();
for (let i = 0; i < all.length; i++) {
  const j = all[i].json;
  const c = proposals[i] || j._candidate || {};
  const verdict = { name: c.name || '(unnamed)', url: c.url || '', type: c.type || 'rss',
                    topic_id: c.topic_id, topic_page_id: c.topic_page_id, why: c.why || '' };

  // 1. did it answer at all
  const status = Number(j.statusCode ?? j.status ?? 200);
  if (j._fetch_failed || status >= 400) {
    results.push({ ...verdict, ok: false, rejected: `no answer: ${j._fetch_error || 'HTTP ' + status}` });
    continue;
  }

  // 2. does it parse into entries. The body arrives as text, so the check is done on the raw markup:
  // running it through the XML node first would mean one invented address throwing and taking the
  // whole discovery run with it — the same failure a dead feed caused on the daily path.
  const raw = String(j.data ?? j.body ?? '');
  if (/^\s*(<!doctype html|<html)/i.test(raw.trim())) {
    results.push({ ...verdict, ok: false, rejected: 'not a feed: serves an HTML page' });
    continue;
  }
  const list = raw.match(/<item[\s>]|<entry[\s>]/gi) || [];
  if (list.length < MIN_ITEMS) {
    results.push({ ...verdict, ok: false, rejected: `does not look like a feed: ${list.length} entries` });
    continue;
  }

  // 3. is it still alive
  // The capture keeps its closing '<', and a lone '<' is not a tag, so stripping tags alone leaves it
  // on the end and every date fails to parse. It showed up as "last: undated" on six live feeds.
  const dates = (raw.match(/<(?:pubDate|published|updated)>([^<]+)</g) || []).map((m) => {
    const v = m.replace(/^<[^>]*>/, '').replace(/<$/, '').trim();
    const iso = DateTime.fromISO(v, { setZone: true });
    return iso.isValid ? iso : DateTime.fromRFC2822(v, { setZone: true });
  }).filter((d) => d && d.isValid);

  const newest = dates.length ? DateTime.max(...dates) : null;
  const staleDays = newest ? Math.round(now.diff(newest, 'days').days) : null;
  if (staleDays !== null && staleDays > MAX_STALE_DAYS) {
    results.push({ ...verdict, ok: false, rejected: `silent for ${staleDays} days` });
    continue;
  }

  // 4. how much it actually publishes — a measured number, not the model's guess
  const oldest = dates.length ? DateTime.min(...dates) : null;
  const spanDays = oldest && newest ? Math.max(1, now.diff(oldest, 'days').days) : null;
  const perWeek = spanDays ? Math.round((list.length / spanDays) * 7) : null;

  results.push({
    ...verdict,
    ok: true,
    items_seen: list.length,
    per_week: perWeek,
    freshness: newest ? newest.toISODate() : null,
    // Goes into the Note so the row explains itself a year later.
    note: `Proposed by the agent on ${now.toISODate()}. ${c.why || ''} Verified: ${list.length} entries, ~${perWeek ?? '?'} per week, last ${newest ? newest.toISODate() : 'undated'}.`.trim(),
  });
}

const passed = results.filter((r) => r.ok);
const failed = results.filter((r) => !r.ok);

return [{
  json: {
    passed,
    failed,
    summary: `${results.length} proposed, ${passed.length} passed verification`,
    // Rejections are shown too. Seeing "invented three feeds that do not exist" is part of what makes
    // the check visible rather than a claim in a README.
    rejected_lines: failed.map((f) => `${f.name} — ${f.rejected}`),
  },
}];

// [35] Survivors become rows; rejects become a line in the message. Both are shown, because "the agent
// invented three feeds that do not exist" is the part that proves the check is real rather than claimed.
//
// Everything lands as `Proposed`. Nothing a model suggested is ever switched on by this workflow.
const d = $input.first().json;
const passed = d.passed || [];
const failed = d.failed || [];

const STRINGS = {
  en: { title: 'Source discovery', passed: 'Passed verification:', perWeek: 'per week', last: 'last',
        inBase: 'They are in the database as Proposed. Set the ones that fit to Active.',
        rejected: 'Rejected:', none: 'No candidates found.' },
  uk: { title: 'Розвідка джерел', passed: 'Пройшли перевірку:', perWeek: 'на тиждень', last: 'останній',
        inBase: 'Вони вже в базі зі статусом Proposed. Постав Active тим, що підходять.',
        rejected: 'Відсіяно:', none: 'Кандидатів не знайшлося.' },
};
const S = STRINGS[(() => { try { return $('Build discovery input').first().json.lang; } catch { return 'en'; } })()] || STRINGS.en;

const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rich = (s) => (s ? [{ type: 'text', text: { content: String(s).slice(0, 2000) } }] : []);

const rows = passed.map((p) => ({
  json: {
    properties: {
      'Source': { title: rich(p.name) },
      'Address': { url: p.url },
      'Type': { select: { name: p.type } },
      'Status': { select: { name: 'Proposed' } },
      'Proposed by': { select: { name: 'agent' } },
      'Failures in a row': { number: 0 },
      'Items per week': { number: Number(p.per_week) || null },
      'Freshness': p.freshness ? { date: { start: p.freshness } } : { date: null },
      'Note': { rich_text: rich(p.note) },
      'Topics': { relation: p.topic_id ? [{ id: p.topic_id }] : [] },
    },
  },
}));

// The message names numbers the code measured, never numbers the model claimed.
const lines = [`🔍 <b>${S.title}</b>`, '', d.summary || ''];
if (passed.length) {
  lines.push('', `<b>${S.passed}</b>`);
  for (const p of passed) {
    lines.push(`• ${esc(p.name)} - ${esc(p.type)}, ~${p.per_week ?? '?'} ${S.perWeek}, ${S.last} ${esc(p.freshness || 'undated')}`);
  }
  lines.push('', `<i>${S.inBase}</i>`);
}
if (failed.length) {
  lines.push('', `<b>${S.rejected}</b>`);
  for (const f of failed) lines.push(`• ${esc(f.name)} — ${esc(f.rejected)}`);
}
if (!passed.length && !failed.length) lines.push('', S.none);

// One item, so the branch keeps flowing even when every candidate was rejected: the checkbox still
// has to be cleared, otherwise discovery would fire again in fifteen minutes, and again after that.
return [{
  json: {
    source_rows: rows.map((r) => r.json),
    message: lines.filter((l) => l !== '' || true).join('\n'),
    passed_count: passed.length,
    failed_count: failed.length,
    topic_page_ids: [...new Set(passed.concat(failed).map((x) => x.topic_page_id).filter(Boolean))],
  },
}];

// [36] One item per verified source to create. Rejected candidates never reach this node and never
// reach the database — the only trace they leave is a line in the report.
const d = $input.first().json;
const rows = d.source_rows || [];

if (rows.length === 0) {
  // Nothing passed, but the branch must continue: the checkbox still has to be cleared, or discovery
  // would fire again in fifteen minutes, and again, and again.
  return [{ json: { nothing_to_create: true } }];
}

return rows.map((r) => ({ json: r }));

// [37] Untick «Find sources» on every topic that asked. Done whether or not anything was found:
// an unanswered request that stays ticked turns a one-off into a loop every quarter of an hour.
const ids = (() => {
  try { return $('Build source rows').first().json.topic_page_ids || []; } catch { return []; }
})();

if (ids.length === 0) return [];
return ids.map((page_id) => ({ json: { page_id } }));

// [41] The weekly review. The only place in the whole system where the person is asked to press
// something — and it asks after the reading has happened, not before.
//
// It shows the week's items, marks which ones were opened, and offers one button per unopened item.
// Switched off with a single field in Налаштування; when off, the filter keeps learning from clicks
// alone and nobody is nagged.
const MAX_LINES = 25;   // one Telegram message; a longer week links to the archive instead

// The few words this node writes itself. The digest's language is a row in Settings; adding another
// language is a row here and nothing else anywhere.
const STRINGS = {
  en: { title: 'The week in numbers', sent: 'sent', opened: 'opened',
        allGood: 'You opened everything that arrived. The filter is working - nothing to change.',
        notOpened: 'These you did not open:', andMore: 'and', rest: 'more - the rest is in the archive',
        mark: 'Mark the ones that were noise in Feed - the Verdict field.',
        noPressure: 'Marking nothing is also an answer: the click counts itself, with no tapping at all.' },
  uk: { title: 'Тиждень у цифрах', sent: 'надіслано', opened: 'відкрито',
        allGood: 'Усе, що приходило, ти відкривав. Фільтр працює - правити нічого.',
        notOpened: 'Це ти не відкрив:', andMore: 'і ще', rest: '- решта в архіві',
        mark: 'Познач у Стрічці ті, що були мимо - поле Вердикт.',
        noPressure: 'Не позначати теж відповідь: клік рахується сам, без жодного натискання.' },
};
const S = STRINGS[(() => { try { return $('Gate').first().json.config.lang; } catch { return 'en'; } })()] || STRINGS.en;

// The week's shipped items, straight off a Notion query of Стрічка.
function prop(page, name) {
  const p = (page.properties || {})[name];
  if (!p) return null;
  switch (p.type) {
    case 'title': return (p.title || []).map((x) => x.plain_text).join('');
    case 'rich_text': return (p.rich_text || []).map((x) => x.plain_text).join('');
    case 'select': return p.select ? p.select.name : null;
    case 'date': return p.date ? p.date.start : null;
    default: return p[p.type] ?? null;
  }
}

const pages = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (Array.isArray(j.results)) pages.push(...j.results);
  else if (j.id || j.properties) pages.push(j);
}

const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const items = pages.map((p) => ({
  page_id: p.id,
  hash: prop(p, 'Hash'),
  title: prop(p, 'Title'),
  opened: !!prop(p, 'Opened'),
  verdict: prop(p, 'Verdict'),
})).filter((i) => i.hash);

const opened = items.filter((i) => i.opened);
const unjudged = items.filter((i) => !i.opened && !i.verdict);

if (items.length === 0) {
  return [{ json: { skip: true, reason: 'nothing shipped this week' } }];
}

const rate = Math.round((opened.length / items.length) * 100);
const lines = [
  `📋 <b>${S.title}</b>`,
  '',
  `${S.sent} ${items.length} · ${S.opened} ${opened.length} (${rate}%)`,
];

if (unjudged.length === 0) {
  lines.push('', S.allGood);
  return [{ json: { skip: false, text: lines.join('\n'), buttons: [] } }];
}

lines.push('', `<b>${S.notOpened}</b>`);

const shown = unjudged.slice(0, MAX_LINES);
shown.forEach((it, n) => lines.push(`${n + 1}. ${esc(it.title)}`));
if (unjudged.length > shown.length) {
  lines.push('', `<i>${S.andMore} ${unjudged.length - shown.length} ${S.rest}</i>`);
}

// No buttons, and the second reason is the real one.
//
// Telegram's node fixes its keyboard at build time, so a list that is eight items one week and two
// the next cannot be a row of buttons without contortions. And a callback needs n8n on a public
// address, which a local install does not have — a feature that works only for some readers is worse
// than one that works the same for everyone.
//
// Marking the verdict in Feed is also more in keeping with the rest of the system: the control
// panel is the database. Open it, set `Verdict` to `miss` on what was noise, done.
lines.push('', `<i>${S.mark}</i>`);
lines.push(`<i>${S.noPressure}</i>`);

return [{
  json: {
    skip: false,
    text: lines.join('\n'),
    stats: { shipped: items.length, opened: opened.length, open_rate: rate, unjudged: unjudged.length },
  },
}];

// [44] Put «Review now» back to «no» once the review has gone out, so asking for it early is a
// one-shot rather than something that repeats every morning until noticed.
const found = ($input.first().json.results || [])[0];
if (!found) return [];

return [{
  json: {
    page_id: found.id,
    properties: { 'Value': { rich_text: [{ type: 'text', text: { content: 'no' } }] } },
  },
}];
